/*==============================================================*/
/* LabControl - 04_datos_prueba.sql                             */
/* Datos precargados para pruebas y defensa.                    */
/* Dialecto: Watcom-SQL (SQL Anywhere 11) - ejecutar en ISQL     */
/* como DBA o admin.                                             */
/*                                                              */
/* Correr DESPUES de 01_tablas.sql, 02_objetos.sql y            */
/* 03_permisos.sql. Es re-ejecutable: el PASO 0 borra todo en   */
/* orden inverso de FKs antes de volver a cargar.               */
/*                                                              */
/* FECHA DE REFERENCIA: hoy = 2026-07-29 (miercoles).           */
/* Si se corre mucho despues de esa fecha, las reservas         */
/* "futuras" del PASO 6 van a empezar a ser rechazadas por el   */
/* trigger de fecha pasada. En ese caso, correr todo el bloque  */
/* del PASO 6 tambien con fire_triggers Off, o correr el ajuste */
/* de fechas del PASO 9.                                        */
/*==============================================================*/
/* POR QUE SE APAGAN LOS TRIGGERS EN EL PASO 5                   */
/*                                                              */
/* Los triggers de RESERVAS validan reglas de OPERACION EN      */
/* LINEA: no reservar en el pasado, no reservar un fin de       */
/* semana, no pisar un mantenimiento. Esas reglas son correctas */
/* para un alta hecha desde la aplicacion, pero impiden cargar  */
/* historial: por definicion, una reserva ya Utilizada o        */
/* Ausente ocurrio en el pasado.                                 */
/*                                                              */
/* Por eso el historial se carga con                             */
/*     SET TEMPORARY OPTION fire_triggers = 'Off';               */
/* que afecta SOLO a esta conexion y solo hasta que se vuelve a */
/* prender. El bloque futuro (PASO 6) se carga con los triggers */
/* ENCENDIDOS a proposito: si alguna fila estuviera mal armada  */
/* (fin de semana, capacidad excedida, solapamiento, duracion   */
/* mayor a la permitida, laboratorio en mantenimiento), el      */
/* script falla ahi mismo. O sea que el PASO 6 funciona como    */
/* prueba de humo de los triggers.                               */
/*==============================================================*/

/*==============================================================*/
/* PASO 0 - LIMPIEZA (orden inverso a las dependencias FK)      */
/*==============================================================*/
SET TEMPORARY OPTION fire_triggers = 'Off';

DELETE FROM RESERVAS_RECURSOS;
DELETE FROM AUDITORIA;
DELETE FROM RESERVAS;
DELETE FROM MANTENIMIENTOS;
DELETE FROM SOLICITANTES;
DELETE FROM RECURSOS;
DELETE FROM LABORATORIOS;
DELETE FROM TIPO_ACTIVIDAD;
DELETE FROM PRIORIDADES;
DELETE FROM TIPOS_SOLICITANTES;
DELETE FROM TIPOS_DOCUMENTOS;
DELETE FROM ESTADO_RESERVA;
DELETE FROM ESTADOS_OPERATIVOS;
DELETE FROM ESTADOS_MANTENIMIENTOS;
DELETE FROM CARRERAS;
DELETE FROM DEPARTAMENTOS;
DELETE FROM PISOS;
DELETE FROM EDIFICIOS;

COMMIT;

/*==============================================================*/
/* PASO 1 - CATALOGOS SIN DEPENDENCIAS                          */
/*==============================================================*/

/*---------------- EDIFICIOS ----------------*/

/*---------------- ESTADOS_MANTENIMIENTOS ----------------*/
/* P=Pendiente, R=Realizado, E=En proceso, C=Cancelado.
   Solo P y E bloquean el laboratorio (fn_existe_mantenimiento). */

/*---------------- ESTADOS_OPERATIVOS ----------------*/
/* D=Disponible, R=Reservado, M=Mantenimiento,
   F=Fuera de servicio, B=Bloqueado.
   M/F/B impiden reservar (tr_validar_estados_operativos_lab). */

/*---------------- ESTADO_RESERVA ----------------*/
/* P=Pendiente, U=Utilizada, C=Cancelada, A=Ausente,
   D=Desplazada (la pone sp_crear_reserva, no se elige a mano). */

/*---------------- TIPOS_DOCUMENTOS ----------------*/

/*---------------- TIPOS_SOLICITANTES ----------------*/

/*---------------- PRIORIDADES ----------------*/
/* Categoria agrupadora que muestra la interfaz. El desempate
   fino real lo hace TIPO_ACTIVIDAD.NIVEL_PRIORIDAD. */

COMMIT;

/*==============================================================*/
/* PASO 2 - DEPENDEN DEL PASO 1                                 */
/*==============================================================*/

/*---------------- PISOS ----------------*/

/*---------------- DEPARTAMENTOS ----------------*/
/* 1-5: Facultad de Ciencias y Tecnologia (edificio 3). */
/* 6-14: edificio Ciencias Contables (edificio 2). Vienen del
   script suelto carreras_ciencias_contables.sql, integrado aca
   con IDs fijos en vez de MAX(ID)+1 para que la carga sea
   determinista y el script siga siendo re-ejecutable. */

/*---------------- TIPO_ACTIVIDAD ----------------*/
/* ID_PRIORIDAD  = categoria visible (Alta / Media Alta / ...).
   NIVEL_PRIORIDAD = valor fino SIN empates (1 = mas fuerte).
   Es el que usan fn_existe_solapamiento_reservas y
   sp_crear_reserva para decidir quien desplaza a quien.
   DURACION_MAX_HORAS la valida el trigger de RESERVAS.

   OJO: ID_TIPO_ACTIVIDAD = 0 (Reunion Directiva) es un valor
   falsy en JavaScript. El backend tiene que preguntar por
   null/undefined explicitamente, no por truthiness. */

COMMIT;

/*==============================================================*/
/* PASO 3 - DEPENDEN DEL PASO 2                                 */
/*==============================================================*/

/*---------------- CARRERAS ----------------*/
/* 1-5: Ciencias y Tecnologia. */
/* 6-14: Ciencias Contables. */

/*---------------- LABORATORIOS ----------------*/
/* Labs 1-3: Ciencias y Tecnologia (edificio 3), disponibles.
   Lab 4: Bloque G, en Mantenimiento (estado 3).
   Lab 5: Bloque G, Fuera de servicio (estado 4).
   Labs 6 y 7: Biblioteca y Ciencias Contables, disponibles,
   para que esos edificios ofrezcan opciones en el flujo movil. */

COMMIT;

/*==============================================================*/
/* PASO 4 - DEPENDEN DEL PASO 3                                 */
/*==============================================================*/

/*---------------- RECURSOS ----------------*/

/*---------------- MANTENIMIENTOS ----------------*/
/* Coherentes con el estado operativo de cada laboratorio y con
   las reservas cargadas mas abajo:
     1. Lab 4 En proceso -> por eso el lab 4 esta en estado M.
     2. Lab 1 Pendiente del 03 al 07/08 -> el PASO 6 NO carga
        ninguna reserva del lab 1 esa semana; si se intenta, el
        trigger la rechaza. Es el caso de demo de la regla.
     3. Lab 5 En proceso -> por eso el lab 5 esta Fuera de servicio.
     4. Lab 2 Realizado (junio) -> historico, ya NO bloquea.
     5. Lab 3 Pendiente en septiembre -> se cancela en el PASO 8
        para generar un renglon de auditoria. */

/*---------------- SOLICITANTES ----------------*/
/* ID_CARRERA es NOT NULL en el modelo, asi que TODO solicitante
   pertenece a una carrera, incluido el personal administrativo:
   los administrativos se asignan a la carrera del area en la que
   trabajan (Administracion de Empresas, Ciencias Contables,
   Marketing), que es lo que se cargo con los departamentos del
   edificio de Ciencias Contables.
   La columna DEPARTAMENTO es la sigla desnormalizada que muestra
   la interfaz sin tener que hacer el JOIN CARRERAS-DEPARTAMENTOS. */
/* Administrativo: antes tenia ID_CARRERA en NULL, lo que ademas
   violaba el NOT NULL de la tabla. Ahora pertenece a DADE. */

COMMIT;


/*==============================================================*/
/* PASO 5 - RESERVAS HISTORICAS (2026-06-15 a 2026-07-22)       */
/*                                                              */
/* SE CARGAN CON LOS TRIGGERS APAGADOS (ver explicacion arriba). */
/* Son reservas que ya ocurrieron, con estados finales:          */
/*   U = Utilizada    A = Ausente (no se presento)               */
/*   C = Cancelada por una persona, con motivo y responsable     */
/*   D = Desplazada automaticamente por una de mayor prioridad   */
/*   P = Pendiente vencida, a proposito: son las que el job      */
/*       ev_cancelar_reservas_vencidas va a pasar a Ausente.     */
/*                                                              */
/* Aunque los triggers no corran, los datos respetan igual todas */
/* sus reglas (dias habiles, capacidad, duracion maxima por tipo */
/* de actividad y sin solapamientos entre reservas vigentes).    */
/* Las Canceladas y Desplazadas SI bloquean nada: por eso puede  */
/* haber una 'D' y una 'U' en el mismo horario, que es           */
/* justamente el par que deja el desplazamiento por prioridad.   */
/*==============================================================*/
SET TEMPORARY OPTION fire_triggers = 'Off';


COMMIT;

/*==============================================================*/
/* PASO 6 - RESERVAS FUTURAS (todas Pendientes)                  */
/*                                                              */
/* TRIGGERS ENCENDIDOS: este bloque es, ademas de carga de       */
/* datos, la prueba de humo de todas las validaciones. Si una    */
/* sola fila estuviera mal, el script corta aca con el RAISERROR */
/* correspondiente.                                              */
/*                                                              */
/* Notar que NO hay ninguna reserva del laboratorio 1 entre el   */
/* 03 y el 07 de agosto: ese lab tiene un mantenimiento          */
/* Pendiente esa semana (mantenimiento 2) y el trigger las       */
/* rechazaria. Tampoco hay reservas de los labs 4 y 5, que estan */
/* en Mantenimiento y Fuera de servicio.                         */
/*==============================================================*/
SET TEMPORARY OPTION fire_triggers = 'On';


COMMIT;

/*==============================================================*/
/* PASO 7 - RECURSOS SOLICITADOS EN CADA RESERVA                */
/*                                                              */
/* Sin estas filas, el reporte "porcentaje de utilizacion de     */
/* recursos" sale vacio. Solo se asocian recursos que pertenecen */
/* al laboratorio de la reserva y que estan DISPONIBILIDAD='S'   */
/* (el backend valida ambas cosas al crear la reserva).          */
/*==============================================================*/
/*==============================================================*/
/* PASO 7 - RECURSOS SOLICITADOS EN CADA RESERVA                */
/*                                                              */
/* NOTA: SQL Anywhere 11 no admite VALUES multi-fila            */
/* (VALUES (a,b),(c,d) recien existe desde la version 12), por  */
/* eso va un INSERT por fila.                                   */
/*==============================================================*/

COMMIT;

/*==============================================================*/
/* PASO 8 - ACTIVIDAD PARA LA AUDITORIA                         */
/*                                                              */
/* La tabla AUDITORIA se llena sola por trigger, pero los PASOS  */
/* 5 y 7 corrieron con los triggers apagados o sobre tablas sin  */
/* auditoria. Estas operaciones se hacen con los triggers        */
/* ENCENDIDOS para que el reporte de auditoria tenga contenido   */
/* de los tres grupos (RESERVA / LABORATORIO / MANTENIMIENTO)    */
/* antes de la defensa.                                          */
/*==============================================================*/
SET TEMPORARY OPTION fire_triggers = 'On';

/* 1) Cancelacion de una reserva -> evento RESERVA_ESTADO.
      El motivo es obligatorio: lo exige tr_validad_cancelacion_reserva. */
UPDATE RESERVAS
SET ID_ESTADO_RESERVA  = (SELECT ID_ESTADO_RESERVA FROM ESTADO_RESERVA WHERE ESTADO_RESERVA = 'C'),
    MOTIVO_CANCELACION = 'Actividad suspendida',
    USUARIO_CANCELACION= 'admin'
WHERE ID_RESERVA = 241;

/* 2) Reprogramacion -> evento RESERVA_REPROGRAMADA.
      Se mueve a una fecha libre (martes 15/09) para no chocar
      con nada ya cargado. */
UPDATE RESERVAS
SET FECHA_A_RESERVAR = '2026-09-15',
    HORA_INICIO      = '09:00:00',
    HORA_FIN         = '11:00:00'
WHERE ID_RESERVA = 242;

/* 3) Cambio de estado operativo de un laboratorio ->
      evento LABORATORIO_ESTADO (dos renglones, ida y vuelta).
      Disponible -> Reservado -> Disponible. No se usa 'Fuera de
      servicio' ni 'Bloqueado' porque esos solo los puede poner
      un administrador (tr_validar_cambio_estado_lab). */
UPDATE LABORATORIOS SET ESTADO = 2 WHERE NUMERO_LABORATORIO = 6;
UPDATE LABORATORIOS SET ESTADO = 1 WHERE NUMERO_LABORATORIO = 6;

/* 4) Cancelacion de un mantenimiento -> evento
      MANTENIMIENTO_ESTADO. Es el de septiembre sobre el lab 3;
      al quedar Cancelado deja de bloquear ese laboratorio. */
UPDATE MANTENIMIENTOS
SET ID_ESTADO_MANTENIMIENTO = (SELECT ID_ESTADO_MANTENIMIENTO FROM ESTADOS_MANTENIMIENTOS WHERE ESTADO_MANTENIMIENTO = 'C')
WHERE ID_MANTENIMIENTO = 5;

/* 5) Reprogramacion de un mantenimiento ->
      evento MANTENIMIENTO_REPROGRAMADO. */
UPDATE MANTENIMIENTOS
SET FECHA_FIN_PREVISTA = '2026-08-21'
WHERE ID_MANTENIMIENTO = 1;

COMMIT;

