/*==============================================================*/
/* PASO 10 - VERIFICACION RAPIDA                                */
/*==============================================================*/
SELECT er.ESTADO_RESERVA, COUNT(*) AS CANTIDAD
FROM RESERVAS r JOIN ESTADO_RESERVA er ON er.ID_ESTADO_RESERVA = r.ID_ESTADO_RESERVA
GROUP BY er.ESTADO_RESERVA ORDER BY 1;

SELECT TIPO_EVENTO, COUNT(*) AS CANTIDAD FROM AUDITORIA GROUP BY TIPO_EVENTO ORDER BY 1;

